/* Links do porquê de Interações Biológicas e Patológicas (Rafael 25/11/2026): afirmação que precisa de explicação. t = trecho exato do texto do site. */
(function(){ var B = window.BANCOS && window.BANCOS.inter; if (!B) return;
  var ROB = 'Kumar, Abbas & Aster, Robbins Patologia Básica; Brasileiro Filho, Bogliolo Patologia Geral';
  var NEV = 'Neville et al., Patologia Oral e Maxilofacial, 4ª ed.';
  var SMS = 'Manual de Lesões Bucais, SMS-SP (2017); Neville et al., Patologia Oral e Maxilofacial, 4ª ed.';
  var MM = 'Marsh & Martin, Microbiologia Oral';
  var TOR = 'Tortora, Funke & Case, Microbiologia';
  var CAR = 'Newman et al., Carranza Periodontia Clínica';
  var ABB = 'Abbas, Lichtman & Pillai, Imunologia Celular e Molecular';
  var AHA = 'Wilson et al., Prevention of Viridans Group Streptococcal Infective Endocarditis, AHA 2021 (Circulation 2021)';
  var WP = 'White & Pharoah, Radiologia Oral: fundamentos e interpretação';
  var ANV = 'ANVISA, Serviços Odontológicos: prevenção e controle de riscos (2006)';
  var FK = 'Fejerskov & Kidd, Cárie Dentária: a doença e seu tratamento clínico';
  var MEL1 = 'Thuaire A et al. 2022, 2.230 casos de melanoma oral; López F et al. 2016, revisão de melanoma de mucosa da cabeça e pescoço';
  var MET = 'Hirshberg A et al. 2008, metástases para a boca (673 casos)';
  var BIO = 'Pflugfelder A et al. 2010 e Bong JL et al. 2002 (biópsia incisional no melanoma); Neville et al., Patologia Oral e Maxilofacial';
  var PIG = 'Santana T et al. Oral Dis 2023 (série brasileira); Gondak RO et al. 2012; Neville et al., Patologia Oral e Maxilofacial';
  B.porques = (B.porques || []).concat([

  /* ---------- Resumo: Interações (biofilme e índice de placa) ---------- */
  { t: "colonizadores iniciais → tardios → biofilme maduro", p: "Cada grupo de bactérias muda o ambiente e prepara a chegada do próximo. Os colonizadores iniciais (estreptococos) têm receptores para a película adquirida e grudam primeiro; eles consomem oxigênio e oferecem superfície para os colonizadores tardios, que se prendem a eles por coagregação e preferem pouco oxigênio. Com camadas e matriz, chega-se ao biofilme maduro. Ex.: 4 horas depois da escovação há quase só estreptococos; depois de uma semana sem escovar aparecem Fusobacterium e anaeróbios.", fonte: MM },
  { t: "corante em bochecho de ~30 s", p: "O corante (eritrosina ou fucsina) precisa de tempo para entrar na matriz do biofilme e tingir as bactérias, mas sem ficar tanto tempo que pinte também a película adquirida e as mucosas. Uns 30 segundos de bochecho espalham o líquido por todas as faces e depois o excesso sai com um enxágue leve. Assim só fica corado o biofilme de verdade. Ex.: na primeira consulta, o paciente bochecha o evidenciador, cospe, e o dentista conta as faces com cor rosa para calcular o O'Leary.", fonte: CAR },
  { t: "Não faz quem tem resina na vestibular dos anteriores ou aparelho", p: "O corante entra nos poros da resina composta e nas borrachas e no adesivo dos bráquetes do aparelho, e pode deixar mancha que não sai na escovação. Como o objetivo é só mostrar o biofilme, não vale o risco de manchar uma restauração da frente, que aparece no sorriso. Ex.: um aluno com faceta de resina nos incisivos superiores participa da aula como operador, e não como paciente da evidenciação.", fonte: CAR },
  { t: "todo paciente de primeira consulta, para ensinar a escovar", p: "O biofilme é quase da cor do dente e o paciente não enxerga onde ele fica. Corado, ele vê exatamente as faces em que a escova não passa, e o dentista tem um número (O'Leary) para comparar nas próximas consultas. Mostrar dá mais resultado que só falar 'escove melhor'. Ex.: um paciente que jura escovar bem vê a faixa rosa na cervical dos molares e passa a inclinar a escova ali.", fonte: CAR },

  /* ---------- Resumo: Patologia geral ---------- */
  { t: "Agressão → adaptação, lesão reversível ou lesão irreversível (morte)", p: "A resposta depende da força e da duração da agressão e da capacidade da célula. Estímulo moderado e persistente leva a célula a mudar de tamanho, número ou tipo para continuar funcionando (adaptação). Se a agressão passa do que ela aguenta, aparece dano que ainda tem volta (lesão reversível). Se continua ou é muito forte, a célula passa do ponto de não retorno e morre por necrose ou apoptose. Ex.: o masseter de um bruxista aumenta (adaptação); a polpa sob uma cárie rasa inflama e se recupera; a polpa de um dente com cárie profunda pode necrosar.", fonte: ROB },
  { t: "Hiperplasia = mais células", p: "Na hiperplasia o tecido aumenta porque as células se dividem mais, o que só acontece em tecidos capazes de mitose, como epitélio e conjuntivo. Ela é uma resposta a estímulo (hormônio, irritação crônica) e para quando o estímulo some, diferente da neoplasia. Na hipertrofia as células só ficam maiores. Ex.: a gengiva de um paciente com prótese mal adaptada cresce em pregas por hiperplasia fibrosa inflamatória.", fonte: ROB },
  { t: "Metaplasia = troca de tipo de célula", p: "Quando um tecido sofre agressão crônica, as células-tronco dele passam a se diferenciar num tipo adulto diferente, mais resistente àquele agressor. É uma troca que protege, mas perde a função original, e se o estímulo continuar pode abrir caminho para displasia. Ex.: no fumante, o epitélio cilíndrico ciliado dos brônquios vira epitélio escamoso, que aguenta a fumaça mas não limpa o muco.", fonte: ROB },
  { t: "Mucocele: lábio inferior, azulada, flutuante, aumenta e diminui", p: "O lábio inferior é o lugar mais mordido e tem muitas glândulas salivares menores. Quando o ducto rompe, o muco escapa para o conjuntivo e forma uma bolsa de líquido: por isso é flutuante. O muco perto da superfície dá cor azulada pela transparência. Ela 'aumenta e diminui' porque a bolsa enche com a saliva e às vezes rompe ou é reabsorvida, voltando a encher depois. Ex.: um adolescente que morde o lábio quando está ansioso aparece com uma bolinha azulada que some e volta.", fonte: NEV },
  { t: "trauma rompe o ducto e o muco extravasa", p: "Na mucocele de extravasamento, a mordida ou um trauma corta o ducto da glândula salivar menor. A glândula continua produzindo saliva, mas o muco sai pelo ducto rompido para dentro do conjuntivo, em vez de chegar à boca. O corpo cerca esse muco com tecido de granulação, sem epitélio (não é cisto verdadeiro). Por isso é preciso remover também a glândula que alimenta a lesão. Ex.: depois de uma batida no lábio jogando futebol, aparece uma bolha mole que não some.", fonte: NEV },

  /* ---------- Biofilme e diagnóstico ---------- */
  { t: "considerar história clínica, características da lesão, localização, tempo de evolução", p: "Lesões muito diferentes podem ter a mesma aparência (uma úlcera pode ser trauma, afta, infecção ou câncer). O que separa uma da outra é o conjunto: há quanto tempo existe, se tem causa local, onde fica, se dói, a idade e os hábitos do paciente. Cada informação tira algumas hipóteses da lista. Ex.: úlcera na borda da língua de um fumante de 60 anos, há 2 meses, sem causa traumática, faz pensar em carcinoma; a mesma úlcera em jovem, perto de um dente quebrado, há 5 dias, sugere úlcera traumática.", fonte: NEV },
  { t: "Obstrução por cálculo (A) é sialolitíase", p: "Na sialolitíase, um depósito de cálcio se forma dentro do ducto da glândula e entope a saída da saliva. A saliva fica presa dentro da glândula, que incha e dói principalmente na hora de comer, quando a produção aumenta. Na mucocele não há entupimento: o ducto rompe e o muco escapa para fora dele. Ex.: um paciente que sente a região embaixo da mandíbula inchar e doer toda vez que come pode ter um sialolito no ducto de Wharton.", fonte: NEV },
  { t: "acontece justamente em células que NÃO se dividem", p: "Quando a célula não consegue se dividir, a única forma de o tecido aumentar a capacidade de trabalho é cada célula crescer: ela fabrica mais proteínas e organelas e fica maior. Por isso a hipertrofia é a adaptação típica do músculo esquelético e do coração. Tecidos que se dividem costumam fazer hiperplasia (às vezes junto). Ex.: o masseter de um paciente com bruxismo fica hipertrofiado e o rosto parece mais quadrado.", fonte: ROB },
  { t: "relações de cooperação, dependência metabólica e competição", p: "No biofilme, as espécies estão muito próximas. Algumas usam o que a outra solta (o lactato do estreptococo vira alimento da Veillonella), outras se ligam umas às outras por coagregação, e outras disputam espaço e açúcar ou soltam substâncias que matam vizinhas (bacteriocinas). O resultado é uma comunidade organizada, com comportamento diferente da bactéria isolada. Ex.: o S. sanguinis produz peróxido que atrapalha o S. mutans, enquanto o Fusobacterium ajuda anaeróbios a se fixarem.", fonte: MM },
  { t: "podem retornar ao estado de normalidade se a agressão for eliminada", p: "Na lesão não letal (reversível) a célula ainda tem membrana inteira e mitocôndrias funcionando, só está inchada ou com metabolismo alterado. Retirando o agressor, ela volta a produzir energia, bombeia a água para fora e se recupera. Se o dano chega à membrana e às mitocôndrias de forma grave, não tem volta. Ex.: a polpa de um dente com cárie rasa fica inflamada, mas volta ao normal depois que a cárie é removida e o dente restaurado.", fonte: ROB },
  { t: "aumento do número de hemácias em indivíduos que vivem em grandes altitudes", p: "Em lugares altos o ar tem menos oxigênio. O rim percebe a hipóxia e libera mais eritropoetina, que manda a medula óssea produzir mais hemácias. Com mais hemácias, o sangue carrega mais oxigênio e o corpo se ajusta ao meio, sem doença. É um exemplo de adaptação do organismo. Ex.: um atleta que treina semanas na altitude volta com mais hemácias e mais fôlego.", fonte: ROB },
  { t: "embora possa também provocar lesões", p: "A defesa usa armas que não escolhem alvo com precisão: enzimas e radicais livres dos neutrófilos, anticorpos e citocinas da inflamação. Elas matam o agressor, mas também ferem as células do próprio tecido. Quando a resposta é forte ou não acaba, o dano causado pela defesa pode ser maior que o do agressor. Ex.: na periodontite, quem destrói o osso alveolar é principalmente a inflamação do hospedeiro contra o biofilme.", fonte: ROB },
  { t: "lesão também envolve alterações moleculares e funcionais", p: "A lesão começa nas moléculas (falta de ATP, entrada de cálcio, proteínas alteradas), passa a mudar a função da célula e só depois aparece como mudança de forma visível no microscópio ou a olho nu. Por isso, olhar apenas a morfologia deixa de fora as fases iniciais. Ex.: no infarto, a célula do coração já parou de funcionar minutos depois da falta de oxigênio (hipóxia), mas a alteração visível no microscópio só aparece horas depois.", fonte: ROB },
  { t: "substituído por epitélio escamoso, mais resistente", p: "O epitélio escamoso estratificado tem várias camadas de células, então aguenta melhor o atrito e as substâncias tóxicas da fumaça que o epitélio cilíndrico de uma camada só. A troca é a metaplasia: protege contra o agressor, mas o novo epitélio não tem cílios nem células de muco, e a limpeza do brônquio piora; se a fumaça continuar, pode evoluir para displasia. Ex.: o fumante passa a tossir muito de manhã, porque o muco não é mais varrido pelos cílios.", fonte: ROB },
  { t: "a gengiva sob a borda cresceu em pregas", p: "A borda da prótese mal adaptada machuca a mucosa de leve e todo dia, por anos. Esse trauma crônico de baixa intensidade estimula o conjuntivo e o epitélio a se multiplicarem, formando dobras de tecido (pregas) que acompanham a borda. É a hiperplasia fibrosa inflamatória. Ex.: um senhor que usa a mesma dentadura há 15 anos aparece com 'folhas' de tecido no fundo de vestíbulo, onde a flange encosta.", fonte: NEV },
  { t: "o osso alveolar perde volume com o tempo", p: "O osso alveolar existe para segurar o dente e recebe o estímulo da mastigação pelo ligamento periodontal. Sem o dente, esse estímulo acaba e o corpo reabsorve o osso que 'não está sendo usado', diminuindo o tamanho e o número das células e da matriz: é atrofia por desuso, uma adaptação ao novo ambiente. Ex.: um paciente desdentado há 20 anos tem rebordo fino e baixo, e a prótese total fica com pouca retenção.", fonte: ROB },
  { t: "passa do ponto de não retorno e morre", p: "A célula aguenta a agressão enquanto as mitocôndrias ainda produzem energia e a membrana segura o conteúdo. Quando a membrana se rompe e as mitocôndrias são destruídas, entra muito cálcio, as enzimas se ativam e digerem a célula por dentro. A partir daí, mesmo tirando o agressor, a célula não se recupera e morre por necrose ou apoptose. Ex.: polpa que ficou sem circulação depois de um trauma forte necrosa e não volta, mesmo sem dor.", fonte: ROB },
  { t: "deixando o conjuntivo exposto, com fundo amarelado", p: "Quando o epitélio inteiro some, o conjuntivo fica descoberto e o sangue extravasa uma proteína chamada fibrina, que se deposita na ferida junto com neutrófilos e restos de células. Essa camada (pseudomembrana) é branco-amarelada e cobre o fundo da úlcera. Em volta, a inflamação deixa um halo vermelho. Ex.: uma afta comum tem o fundo amarelado e o halo vermelho ao redor.", fonte: NEV },
  { t: "na linha de oclusão de um paciente que morde a bochecha", p: "A mucosa jugal na altura em que os dentes se encontram é o lugar que mais leva mordida. O trauma repetido estimula o conjuntivo a produzir colágeno e forma um nódulo firme da cor da mucosa: o fibroma traumático. A localização na linha de oclusão já sugere que a causa é a mordida. Ex.: um estudante que morde a bochecha nas provas aparece com uma bolinha dura na mucosa jugal, bem na altura dos molares.", fonte: NEV },
  { t: "a resposta inflamatória do hospedeiro que destrói os tecidos de suporte", p: "As bactérias do biofilme subgengival causam pouco dano direto. O que destrói o periodonto é a resposta do corpo: o LPS e outras moléculas das bactérias estimulam citocinas que ativam enzimas que quebram colágeno e estimulam os osteoclastos a reabsorver osso. Como o biofilme continua lá, a inflamação não termina e o ligamento e o osso vão sendo perdidos. Ex.: um fumante com diabetes descompensada perde osso mais rápido que outro com a mesma quantidade de biofilme.", fonte: CAR },
  { t: "depende da intensidade, do tempo de atuação e da capacidade de reação", p: "Uma mesma agressão pode passar sem dano, causar adaptação ou matar a célula. Isso depende de quão forte é o agressor, de quanto tempo ele age e do estado de quem recebe (idade, nutrição, imunidade, doenças). Por isso dois pacientes reagem diferente ao mesmo estímulo. Ex.: o mesmo biofilme dá só gengivite num jovem saudável e periodontite grave num diabético descompensado.", fonte: ROB },
  { t: "consistência óssea e recobertos por mucosa de aspecto normal", p: "O tórus é osso maduro a mais, crescendo devagar por baixo da mucosa, sem inflamação nem tumor. Por isso é duro como osso à palpação e a mucosa por cima tem cor e textura normais, só fica esticada. Isso o diferencia de lesões de tecido mole, que são mais moles, e de tumores, que costumam alterar a mucosa ou crescer rápido. Ex.: um paciente de 42 anos descobre 'caroços duros' embaixo da língua que sempre teve e nunca doeram: tórus mandibular.", fonte: NEV },
  { t: "Se houvesse perda de inserção, seria periodontite", p: "Na gengivite a inflamação fica só na gengiva: o ligamento periodontal e o osso continuam inteiros, e o fundo do sulco permanece no mesmo lugar. Quando a inflamação passa a destruir as fibras de inserção e o osso, o fundo do sulco desce pela raiz (perda de inserção) e forma a bolsa: aí é periodontite. A sondagem mostra a diferença. Ex.: um jovem com gengiva vermelha que sangra, mas com sondagem de 2 a 3 mm sem perda de inserção, tem gengivite.", fonte: CAR },
  { t: "reversível com controle do biofilme", p: "Como a gengivite é inflamação causada pelo biofilme na margem gengival, sem destruição do suporte, tirar o biofilme remove a causa e a inflamação some. Em uma a duas semanas de boa escovação e fio dental a gengiva volta a ficar rosa e firme. Ex.: no estudo clássico de gengivite experimental, estudantes que pararam de escovar tiveram gengivite em cerca de 3 semanas, e ela sumiu dias depois de voltarem a escovar.", fonte: CAR },
  { t: "dentina e cemento têm pH crítico mais alto", p: "Dentina e cemento têm menos mineral que o esmalte, mais matéria orgânica e cristais menores, com mais carbonato, que dissolvem com mais facilidade. Por isso começam a perder mineral já em pH perto de 6,2 a 6,7, enquanto o esmalte aguenta até cerca de 5,5. A raiz exposta é mais vulnerável. Ex.: um idoso com recessão gengival pode ter cárie de raiz com uma dieta que não faria lesão no esmalte.", fonte: FK },
  { t: "Lactobacilos não são pioneiros", p: "Os lactobacilos aderem mal à película adquirida do esmalte liso e precisam de ambiente já ácido e retentivo para crescer. Por isso não estão entre os primeiros a colonizar o dente; quem chega primeiro são estreptococos como S. sanguinis e S. mitis. Os lactobacilos aparecem depois, nas cavidades e na dentina amolecida, ajudando a lesão a progredir. Ex.: no biofilme de 1 dia de um dente sadio quase não se encontra lactobacilo.", fonte: MM },
  { t: "o flúor diminui a solubilidade", p: "O fluoreto ocupa o lugar da hidroxila na hidroxiapatita e forma fluorapatita, um cristal mais estável que precisa de pH mais baixo (cerca de 4,5) para dissolver. Com menos dissolução e com o flúor ajudando a remineralização, o esmalte resiste melhor ao ácido do biofilme. Ex.: a superfície do esmalte de quem usa dentifrício com flúor perde menos mineral na mesma queda de pH.", fonte: FK },
  { t: "especialmente na presença de inflamação gengival", p: "A gengiva inflamada tem vasos dilatados e um epitélio do sulco fino e cheio de pequenas feridas. Ao escovar, mastigar ou passar fio, as bactérias do biofilme entram nesses vasos com facilidade e caem no sangue (bacteremia). Somadas, essas bacteremias diárias são muito maiores que as de uma consulta. Ex.: um paciente com gengivite que sangra ao escovar joga bactérias na corrente sanguínea todo dia, por isso cuidar da gengiva é a melhor prevenção de endocardite.", fonte: AHA },
  { t: "portadores de próteses valvares cardíacas podem necessitar de profilaxia antibiótica", p: "Uma prótese valvar é um material estranho dentro do coração, onde bactérias que chegam pelo sangue grudam com facilidade e formam vegetações, difíceis de tratar e com alta mortalidade. Por isso esses pacientes são de alto risco, e a AHA indica dose única de antibiótico antes de procedimentos que manipulam gengiva ou região periapical. Ex.: paciente com válvula mecânica que vai fazer raspagem recebe amoxicilina 2 g uma hora antes.", fonte: AHA },
  { t: "a saúde bucal é a principal prevenção", p: "A maioria das endocardites de origem oral não vem do consultório, e sim das bacteremias que acontecem todo dia ao escovar e mastigar com a gengiva inflamada. O antibiótico de antes do procedimento cobre só um momento; uma boca saudável diminui as bacteremias de todos os dias. Ex.: um paciente com prótese valvar que mantém gengiva saudável tem menos bactérias no sangue no dia a dia do que receberia de proteção com uma dose de antibiótico.", fonte: AHA },
  { t: "o diagnóstico já é claro pela radiografia oclusal", p: "O sialolito é feito de sais de cálcio e aparece como uma imagem radiopaca (branca) no trajeto do ducto. A radiografia oclusal mostra o assoalho da boca de cima para baixo, bem no caminho do ducto de Wharton, então o cálculo aparece claramente. Com a imagem e a clínica (dor ao comer), não é preciso biópsia. Ex.: o paciente com a glândula submandibular inchada ao comer faz uma oclusal inferior, e o cálculo aparece como um grãozinho branco perto da carúncula.", fonte: WP },
  { t: "Pequeno e perto do orifício, a conduta conservadora é ordenhar", p: "Quando o cálculo é pequeno e já está quase saindo pela abertura do ducto, a massagem da glândula empurra a saliva por trás dele e ajuda a expulsá-lo pelo próprio orifício. Estimular a saliva (com limão, por exemplo) aumenta essa pressão. Assim se evita cortar o ducto, que pode cicatrizar estreito. Cirurgia fica para cálculos grandes ou mais para trás. Ex.: o dentista massageia a submandibular de trás para a frente e o sialolito aparece na carúncula sublingual.", fonte: NEV },
  { t: "frequentemente relacionadas à glândula sublingual", p: "A glândula sublingual fica no assoalho da boca e solta saliva continuamente por vários ductos pequenos, mesmo sem estímulo. Se um desses ductos rompe, o muco escapa sem parar para o assoalho e forma uma grande coleção, que é a rânula. Por isso tirar a sublingual resolve a maioria dos casos. Ex.: uma criança com aumento azulado de um lado do assoalho, que levanta a língua, tem uma rânula da sublingual.", fonte: NEV },
  { t: "tendem a ser maiores que mucoceles em outras localizações intraorais", p: "No assoalho da boca os tecidos são frouxos e há espaço para o muco se espalhar, e a sublingual produz saliva sem parar. No lábio a lesão fica presa num tecido mais firme e costuma romper antes de crescer. Por isso a rânula fica grande e pode até levantar a língua. Ex.: uma mucocele de lábio raramente passa de 1 cm, enquanto uma rânula pode ocupar metade do assoalho.", fonte: NEV },
  { t: "a marsupialização recidiva muito", p: "Na marsupialização se abre a lesão e se costura a borda na mucosa, mas a glândula sublingual continua lá produzindo muco pelo ducto rompido. Quando a abertura fecha, a coleção volta a se formar. Por isso o tratamento mais eficaz é tirar a glândula sublingual junto. Ex.: uma rânula tratada só com marsupialização volta em boa parte dos casos e acaba precisando de exérese da sublingual.", fonte: NEV },

  /* ---------- Lesões fundamentais e lesões da boca ---------- */
  { t: "variação da normalidade, sem tratamento", p: "Os grânulos de Fordyce são glândulas sebáceas que ficaram na mucosa durante a formação do rosto. São tão comuns que fazem parte da anatomia normal: não crescem, não doem e não viram câncer. Tratar não traz benefício e o diagnóstico é só clínico, pela aparência típica de várias pápulas amareladas. Ex.: um aluno que vê pontinhos amarelos na bochecha do colega durante o exame clínico só anota 'grânulos de Fordyce' e segue o exame.", fonte: SMS },
  { t: "Leucoplasia é diagnóstico de exclusão", p: "Leucoplasia não descreve uma doença com causa definida: é o nome dado à placa branca que sobra depois que todas as outras causas conhecidas foram afastadas (candidíase que sai na raspagem, queratose friccional que some ao tirar o trauma, líquen plano, leucoedema). Só então ela recebe esse nome e vai para biópsia, porque pode ter displasia. Ex.: placa branca na borda da língua que não sai na raspagem e não some 4 semanas depois de alisar um dente cortante vira leucoplasia.", fonte: NEV },
  { t: "A candidíase pseudomembranosa sai na raspagem", p: "As placas brancas da candidíase pseudomembranosa são um 'creme' de fungos, células descamadas e restos que fica por cima do epitélio, sem estar preso a ele. Por isso a gaze remove a placa e deixa a mucosa vermelha embaixo. Já na leucoplasia o branco é queratina dentro do próprio epitélio e não sai. Ex.: um bebê com 'sapinho' tem placas que saem com a gaze; um fumante com leucoplasia, não.", fonte: NEV },
  { t: "de crescimento rápido, que sangra com facilidade, comum na gestação", p: "O granuloma piogênico é um tecido de granulação exagerado, cheio de vasos novos e quase sem colágeno, então cresce rápido e sangra ao menor toque. Na gestação, o estrogênio e a progesterona aumentam a resposta dos vasos da gengiva à irritação do biofilme e do cálculo, por isso ele aparece mais (granuloma gravídico) e muitas vezes regride depois do parto. Ex.: uma gestante no 2º trimestre com uma bolinha vermelha na papila entre os incisivos que sangra ao escovar.", fonte: NEV },
  { t: "fica latente no gânglio trigeminal", p: "Depois da primeira infecção, o HSV-1 entra nas terminações nervosas da boca e sobe pelo nervo até o gânglio trigeminal, onde fica 'adormecido' dentro do neurônio, fora do alcance dos anticorpos. Sol, febre, estresse ou baixa imunidade o reativam: ele desce pelo nervo e causa as vesículas sempre na mesma região. Ex.: uma aluna que tem herpes labial no mesmo canto do lábio toda semana de prova.", fonte: NEV },
  { t: "vesículas que se rompem e formam crostas", p: "O vírus se multiplica nas células do epitélio e elas incham e se separam, formando bolinhas de líquido (vesículas). O teto delas é fino e rompe fácil, deixando uma úlcera rasa; no lábio, fora da boca, o líquido seca e vira crosta. Antes disso a pessoa sente ardência e formigamento. Ex.: o herpes labial começa com formigamento, vira um grupo de vesículas e depois uma casquinha que sai em 7 a 10 dias.", fonte: NEV },
  { t: "antibiótico não trata herpes", p: "Antibiótico age em estruturas que só as bactérias têm, como a parede de peptidoglicano. O herpes é um vírus, que se multiplica usando a maquinaria da célula humana e não tem parede, então o antibiótico não o atinge. Para o herpes se usa antiviral (aciclovir), de preferência no começo. Ex.: um paciente com herpes labial que toma amoxicilina por conta própria não melhora nada e ainda desequilibra a microbiota.", fonte: NEV },
  { t: "Metástase é a marca da malignidade", p: "Crescimento rápido, mal delimitado e células atípicas aparecem com frequência no câncer, mas também podem aparecer em lesões benignas agressivas. Já a capacidade de soltar células que viajam pelo sangue ou pela linfa e crescem em outro órgão só existe no tumor maligno. Por isso a metástase é o critério que define malignidade. Ex.: um ameloblastoma pode destruir muito osso e ainda ser benigno; um carcinoma espinocelular que chega aos linfonodos do pescoço é maligno.", fonte: ROB },
  { t: "juntos o risco aumenta muito", p: "As substâncias do tabaco lesam o DNA das células do epitélio e podem levar a displasia. O álcool deixa a mucosa mais permeável, ajudando essas substâncias a entrar, e ainda gera acetaldeído, que também é cancerígeno. Um potencializa o outro, então o risco de quem fuma e bebe é bem maior que a soma dos riscos separados. Ex.: um homem de 60 anos que fuma e bebe todo dia tem risco de carcinoma espinocelular de boca muitas vezes maior que quem só fuma.", fonte: NEV },
  { t: "O cisto periapical é o cisto odontogênico mais comum", p: "A cárie é muito comum e muitas vezes chega à polpa e a necrosa. As bactérias e toxinas saem pelo ápice e causam inflamação crônica no osso, que estimula restos epiteliais (de Malassez) a proliferar e formar a cápsula do cisto. Como a causa é tão frequente, esse cisto também é. Ex.: um dente com cárie antiga e polpa necrosada mostra na radiografia uma imagem redonda e escura em volta do ápice.", fonte: NEV },
  { t: "O dentígero envolve a coroa de dente incluso", p: "O cisto dentígero se forma a partir do epitélio que envolvia a coroa durante a formação do dente (epitélio reduzido do órgão do esmalte). Quando o dente fica preso no osso, líquido se acumula entre esse epitélio e a coroa, e o cisto fica preso no colo do dente, envolvendo a coroa. Ex.: um terceiro molar inferior incluso aparece na panorâmica com uma imagem radiolúcida em volta da coroa.", fonte: NEV },

  /* ---------- Melanoma e lesões pigmentadas ---------- */
  { t: "pode ser até o primeiro sinal da disseminação", p: "Células do tumor que caem no sangue podem se fixar em qualquer tecido com boa circulação, e a gengiva inflamada e o osso dos maxilares são lugares favoráveis. Às vezes a metástase da boca dá sintomas antes que o paciente perceba o tumor original ou outras metástases. Por isso perguntar sobre câncer prévio na anamnese muda o raciocínio. Ex.: na série de 673 casos, cerca de um quarto das metástases orais foi o primeiro sinal de que o câncer tinha se espalhado.", fonte: MET },
  { t: "Em lesão grande de mucosa a biópsia incisional é a recomendada", p: "Tirar uma lesão extensa inteira no consultório deixaria uma ferida enorme, provavelmente com margem insuficiente, e atrapalharia a cirurgia definitiva planejada pela oncologia. A biópsia incisional retira um pedaço representativo, dá o diagnóstico e deixa o tratamento completo para a equipe certa. Ex.: manchas negras espalhadas pela gengiva e pelo palato: o dentista tira um fragmento da área mais suspeita e encaminha o paciente.", fonte: BIO },
  { t: "a biópsia incisional não mudou recidiva nem morte", p: "Existia o medo de que cortar um pedaço do melanoma espalhasse células do tumor. Estudos comparando pacientes que fizeram biópsia incisional com os que fizeram excisional não mostraram diferença em recidiva nem em sobrevida. Como sem diagnóstico não há tratamento certo, a biópsia continua indicada. Ex.: na série de 761 pacientes com melanoma de pele, quem fez biópsia incisional teve a mesma evolução de quem fez excisional.", fonte: BIO },
  { t: "Cirurgia radical com margem de segurança", p: "O melanoma de mucosa responde pouco à radioterapia e à quimioterapia isoladas, então a melhor chance de controle é retirar todo o tumor. Como ele se espalha por baixo da mucosa além do que se vê, é preciso tirar uma margem de tecido sadio em volta para não deixar células para trás. Ex.: um melanoma do palato sem metástase é tratado com ressecção ampla do palato, às vezes com radioterapia depois.", fonte: MEL1 },
  { t: "a quimioterapia tem pouco efeito", p: "As células do melanoma de mucosa costumam ser resistentes aos quimioterápicos clássicos, que atacam células em divisão de forma geral. Nas séries publicadas, a quimioterapia raramente diminui o tumor ou aumenta a sobrevida, por isso não é a base do tratamento. Ex.: um paciente com melanoma oral avançado, já com metástase, costuma receber imunoterapia, e não quimioterapia isolada.", fonte: MEL1 },
  { t: "BRAF aparece em cerca de 7% dos melanomas de mucosa", p: "O melanoma de pele nasce em células expostas ao sol, e a radiação UV favorece mutações como a BRAF V600E. A mucosa da boca quase não recebe sol, então o melanoma ali tem outro perfil de mutações (mais KIT e NRAS). Por isso os remédios anti-BRAF, que funcionam bem na pele, servem para poucos pacientes com melanoma oral. Ex.: no teste genético do tumor de um melanoma do palato, a BRAF geralmente vem negativa.", fonte: MEL1 },
  { t: "a mutação de KIT é mais comum na mucosa", p: "O KIT é um receptor que, quando mutado, deixa o melanócito sempre 'ligado' para se multiplicar. Esse tipo de mutação aparece mais em melanomas de áreas sem sol, como mucosas, palmas e plantas. Quando presente, abre a possibilidade de remédios que bloqueiam o KIT. Ex.: num melanoma de gengiva, o oncologista pede pesquisa de KIT na peça da biópsia antes de escolher a terapia.", fonte: MEL1 },
  { t: "A gengiva inserida concentra cerca de metade das metástases", p: "A gengiva inflamada tem muitos vasos pequenos, com fluxo lento, onde as células do tumor que circulam no sangue se fixam mais fácil. Na série de 673 casos, mais de metade das metástases de partes moles da boca estava na gengiva. Ex.: um paciente com câncer de pulmão aparece com um crescimento vermelho na gengiva, que na biópsia é metástase.", fonte: MET },
  { t: "a lesão parece reativa, por isso pode ser subestimada", p: "A metástase na gengiva cresce como um nódulo vermelho e sangrante, muito parecido com o granuloma piogênico ou a épulis, que são lesões comuns e benignas. Se o dentista não perguntar sobre câncer prévio e não mandar a peça para exame, pode tratar como lesão reativa e perder o diagnóstico. Ex.: uma 'bolinha que sangra' removida sem histopatológico pode ser uma metástase de rim.", fonte: MET },
  { t: "sem sintoma em cerca de 78% dos casos", p: "No começo o melanoma oral é só uma mancha plana, que não dói, não sangra e não atrapalha a mastigação. Como não incomoda, o paciente não procura ajuda, e a lesão só é notada quando já está grande ou ulcerada. Por isso o exame de toda a mucosa na consulta de rotina é a principal chance de diagnóstico cedo. Ex.: na série de 2.230 casos, a grande maioria dos pacientes não tinha sintoma quando a lesão foi achada.", fonte: MEL1 },
  { t: "O palato duro é o sítio número 1 do melanoma oral primário", p: "Os melanócitos da boca são mais numerosos no palato duro e na gengiva superior, e é desses melanócitos que o melanoma nasce. Nas grandes séries, palato e gengiva superior somam a maior parte dos casos. Por isso toda mancha escura nova no palato de adulto merece biópsia. Ex.: na série de 2.230 casos, o palato duro foi o local mais frequente do melanoma oral.", fonte: MEL1 },
  { t: "cerca de 1 em cada 4 melanomas orais não tinha pigmento", p: "Alguns melanomas perdem a capacidade de fabricar melanina; são os amelanóticos. Sem a cor escura, eles aparecem como nódulo ou mancha vermelha ou rosada e são confundidos com granuloma piogênico ou outras lesões vermelhas. Por isso lesão vermelha sem causa no palato também vai para biópsia. Ex.: um tumor rosado no palato duro de um idoso, sem nenhuma pinta preta, pode ser melanoma amelanótico.", fonte: 'de Arruda JAA et al. Head Neck Pathol 2026 (PMC13275972); López F et al. 2016' },
  { t: "S-100 é o mais sensível, HMB-45 é considerado mais específico", p: "Na imuno-histoquímica, anticorpos marcados se ligam a proteínas das células. A S-100 aparece em quase todo melanoma (por isso é sensível), mas também em nervos e outras células. O HMB-45 reconhece uma proteína quase só de melanócitos (mais específico), mas nem todo melanoma tem. Por isso se usa um painel, juntando os marcadores. Ex.: o patologista pede S-100, HMB-45, Melan-A e SOX10 numa biópsia de lesão pigmentada atípica.", fonte: NEV },
  { t: "Nenhum marcador sozinho fecha o diagnóstico", p: "Cada marcador tem falhas: alguns aparecem em outras células (falso positivo), outros somem em certos melanomas (falso negativo). O diagnóstico final junta o painel de imuno-histoquímica com o aspecto das células na lâmina e com a clínica. Ex.: uma lesão S-100 positiva pode ser um tumor de nervo; só com HMB-45, Melan-A e a morfologia o patologista confirma melanoma.", fonte: NEV },
  { t: "A radiografia mostra o metal", p: "O amálgama tem prata, estanho e mercúrio, metais muito densos que barram o raio X. Fragmentos que entraram na mucosa durante uma restauração ou extração aparecem na radiografia como pontinhos radiopacos (brancos). Se eles aparecem embaixo da mancha, o diagnóstico de tatuagem por amálgama está feito sem biópsia. Ex.: mancha cinza-azulada na gengiva ao lado de um dente com amálgama antigo, com pontinhos brancos na periapical.", fonte: NEV },
  { t: "É a pigmentação mais comum da boca", p: "A pigmentação racial é fisiológica: pessoas de pele mais escura têm melanócitos mais ativos, que produzem mais melanina também na gengiva. Como depende da etnia e não de doença, aparece em grande parte da população, dos dois lados e de forma simétrica, desde a infância. Ex.: uma paciente negra de 60 anos com faixa marrom simétrica na gengiva inserida 'desde sempre' só precisa de acompanhamento.", fonte: PIG },
  { t: "Mancha nova, única ou que muda é que pede investigação", p: "As pigmentações benignas costumam ser antigas, simétricas e estáveis, porque vêm da constituição da pessoa ou de causa conhecida. Uma mancha que aparece do nada, só de um lado, ou que cresce e muda de cor é o comportamento esperado de uma lesão melanocítica em proliferação, inclusive o melanoma. Ex.: uma mancha marrom no palato que o paciente não tinha no ano passado vai para biópsia.", fonte: PIG },
  { t: "A mácula melanótica é a lesão focal mais comum", p: "A mácula melanótica é um aumento local de melanina, muitas vezes sem aumento do número de melanócitos, e aparece em lábio, gengiva e palato. É benigna e muito frequente, por isso domina as séries de lesões pigmentadas focais. Ex.: na série brasileira, 191 das 339 lesões melanocíticas focais eram máculas melanóticas.", fonte: PIG },
  { t: "clareia quando a pessoa para de fumar", p: "Substâncias da fumaça do cigarro estimulam os melanócitos da gengiva a produzir mais melanina, talvez como forma de proteger a mucosa. Quando o estímulo acaba, a produção volta ao normal e a melanina antiga é aos poucos removida, por isso a mancha clareia em meses ou anos. Ex.: um paciente que largou o cigarro percebe que a faixa marrom da gengiva de baixo ficou mais clara.", fonte: NEV },
  { t: "típica da gengiva inferior vestibular", p: "A fumaça bate primeiro na parte da frente da boca, e a gengiva vestibular anterior inferior é a região mais exposta e mais usada no contato com o cigarro. Por isso é ali que os melanócitos mais recebem estímulo. Em quem fuma cachimbo, a mancha pode aparecer na mucosa jugal. Ex.: um fumante pesado de 38 anos com faixa marrom na gengiva de baixo, na frente, tem melanose do fumante por excesso de melanina.", fonte: NEV },
  { t: "falta cortisol, o ACTH sobe e estimula os melanócitos", p: "Na doença de Addison as adrenais não produzem cortisol suficiente. A hipófise tenta compensar e libera muito ACTH, que vem da mesma molécula precursora do hormônio que estimula os melanócitos (MSH) e também age nos receptores deles. Com o estímulo, pele e mucosa escurecem de forma difusa. Ex.: uma paciente cansada, com pressão baixa e manchas difusas na bochecha e na pele precisa ser encaminhada ao médico.", fonte: NEV },
  { t: "O melanoma oral é raro: cerca de 0,5% dos cânceres de boca", p: "A mucosa da boca tem bem menos melanócitos que a pele e não recebe radiação UV, que é o grande causador do melanoma cutâneo. Já o epitélio da boca é muito exposto a tabaco e álcool, que causam carcinoma espinocelular. Por isso quase todo câncer de boca é carcinoma e o melanoma é raro. Ex.: um cirurgião de cabeça e pescoço vê dezenas de carcinomas para cada melanoma oral.", fonte: MEL1 },
  { t: "a sobrevida em 5 anos fica", p: "O melanoma oral é achado tarde porque não dói, a mucosa tem muitos vasos e linfáticos que facilitam a metástase, e a área do palato e da gengiva dificulta cirurgia com margem ampla. Além disso, as mutações dele respondem pouco à terapia-alvo. Por isso a sobrevida em 5 anos fica baixa, bem pior que a do melanoma fino de pele. Ex.: na série de 2.230 casos, só cerca de um terço dos pacientes estava vivo 5 anos depois.", fonte: MEL1 },

  /* ---------- Revisão SM1 (60 de concurso) ---------- */
  { t: "extravasa conteúdo e costuma gerar inflamação", p: "Na necrose a membrana da célula se rompe e o conteúdo de dentro (enzimas, restos de DNA, proteínas) cai no tecido. Esse material é reconhecido pelo corpo como sinal de perigo e atrai neutrófilos e macrófagos, iniciando a inflamação em volta. Ex.: polpa necrosada solta seu conteúdo pelo ápice e provoca inflamação no osso periapical.", fonte: ROB },
  { t: "regulada pelo próprio organismo, e não gera inflamação", p: "Na apoptose a célula se desmonta de forma organizada: encolhe, o núcleo se fragmenta e ela se divide em pedacinhos envoltos por membrana, que expõem um sinal de 'me coma'. Os macrófagos fagocitam esses pedaços antes de o conteúdo vazar, então não há sinal de perigo nem inflamação. Ex.: na formação do dente, células do órgão do esmalte morrem por apoptose sem causar inflamação.", fonte: ROB },
  { t: "vasodilatação e ao aumento do fluxo sanguíneo local", p: "Logo no começo da inflamação, mediadores como histamina e prostaglandinas relaxam as arteríolas. Com os vasos mais largos, chega mais sangue à área, e a pele ou a mucosa fica vermelha (rubor). O mesmo sangue a mais traz calor. Ex.: a gengiva com gengivite fica vermelho-viva porque os vasos estão dilatados e cheios de sangue.", fonte: ROB },
  { t: "aumento da temperatura em uma área inflamada", p: "O sangue vem do interior do corpo, que é mais quente que a superfície. Com a vasodilatação, chega mais sangue quente à região, que fica mais quente que o tecido em volta (calor local). Na inflamação extensa, citocinas também agem no cérebro e dão febre. Ex.: a face de um paciente com abscesso dentário fica quente ao toque do lado afetado.", fonte: ROB },
  { t: "Início rápido e duração relativamente curta", p: "A inflamação aguda é a primeira resposta do corpo: em minutos os vasos dilatam, saem líquido e neutrófilos, e o agressor costuma ser eliminado em horas ou poucos dias. Se ele some, a resposta é desligada e o tecido repara. Se não some, a inflamação vira crônica. Ex.: a pericoronarite que começa num dia e melhora em poucos dias com limpeza é uma inflamação aguda.", fonte: ROB },
  { t: "chegam primeiro e predominam nas primeiras 24 a 48 h", p: "Os neutrófilos são os glóbulos brancos mais numerosos no sangue, respondem rápido aos sinais químicos da inflamação e grudam e atravessam a parede dos vasos em poucas horas. Eles vivem pouco no tecido e, depois de 1 a 2 dias, são substituídos pelos monócitos que viram macrófagos. Ex.: o pus de um abscesso agudo é feito principalmente de neutrófilos mortos.", fonte: ROB },
  { t: "A crônica tem infiltrado de mononucleares", p: "Quando o agressor persiste, a resposta muda: chegam monócitos (que viram macrófagos), linfócitos e plasmócitos, células de núcleo único (mononucleares), que mantêm a defesa por semanas ou meses e produzem citocinas e anticorpos. Ao mesmo tempo, há formação de vasos e fibrose. Ex.: o granuloma periapical de um dente com polpa necrosada há meses mostra muitos linfócitos, plasmócitos e macrófagos.", fonte: ROB },
  { t: "Quando vira cicatriz, é reparo (fibrose)", p: "Alguns tecidos têm células que se dividem e repõem o que foi perdido igual ao original (regeneração). Quando a perda é grande ou as células não se dividem, o espaço é preenchido por tecido de granulação, e os fibroblastos depositam colágeno: o resultado é uma cicatriz, que tapa o buraco mas não tem a função do tecido original. Ex.: uma úlcera grande da afta maior deixa cicatriz na mucosa.", fonte: ROB },
  { t: "Biofilme parado na margem gengival inflama a gengiva", p: "As bactérias do biofilme na margem soltam LPS, enzimas e outras moléculas que atravessam o epitélio do sulco, que é fino. O conjuntivo da gengiva reage com inflamação: os vasos dilatam, chegam neutrófilos, e a gengiva fica vermelha, inchada e sangra. Ex.: depois de 2 a 3 semanas sem escovar, quase todo mundo desenvolve gengivite.", fonte: CAR },
  { t: "atrapalha a adesão dos microrganismos", p: "A IgA secretora é a principal imunoglobulina da saliva. Ela se liga às adesinas das bactérias e as cobre, impedindo que se encaixem nos receptores da mucosa e da película adquirida. Além disso, junta bactérias em grupos que são engolidos. Ela não mata a bactéria, mas impede que ela se fixe. Ex.: pacientes com deficiência de IgA têm mais infecções de mucosa.", fonte: ABB },
  { t: "Plasmócito (linfócito B diferenciado) produz anticorpo", p: "Quando o linfócito B reconhece um antígeno e recebe ajuda do linfócito T, ele se multiplica e se transforma em plasmócito, uma célula cheia de retículo endoplasmático rugoso, que é a 'fábrica' de proteínas. Ali ela produz milhares de anticorpos por segundo. Ex.: na inflamação crônica da gengiva, muitos plasmócitos produzem anticorpos contra as bactérias do biofilme.", fonte: ABB },
  { t: "Inata: já nasce com a gente e responde rápido", p: "A imunidade inata usa barreiras e células que já estão prontas antes de qualquer infecção (pele, mucosa, saliva, neutrófilos, macrófagos) e reconhecem padrões comuns a muitos microrganismos. Como não precisa aprender, responde em minutos ou horas. A adaptativa precisa de dias para criar linfócitos e anticorpos específicos. Ex.: um corte na gengiva atrai neutrófilos em poucas horas, antes de existirem anticorpos.", fonte: ABB },
  { t: "a desinfecção não garante esporos", p: "Os esporos são formas de resistência de algumas bactérias, com capa grossa e quase sem água, que aguentam álcool, desinfetantes comuns e fervura. A desinfecção mata a maioria dos microrganismos vivos em atividade, mas não chega a matar esporos com segurança. Só a esterilização (autoclave) garante. Ex.: o instrumento cirúrgico que vai entrar no osso tem que ser autoclavado; passar álcool não basta.", fonte: ANV },
  { t: "não substitui a esterilização", p: "A desinfecção reduz microrganismos em superfícies e objetos que não entram em tecido estéril, mas pode deixar esporos e alguns resistentes vivos. Instrumentos que cortam ou penetram tecido (críticos) precisam estar totalmente livres de microrganismos, o que só a esterilização garante. Ex.: a bancada e o refletor são desinfetados; a cureta e a pinça são esterilizadas na autoclave.", fonte: ANV },
  { t: "Lavar as mãos corta a transmissão cruzada", p: "As mãos tocam paciente, instrumentos, superfícies e outros pacientes, levando microrganismos de um lugar para outro (infecção cruzada). A higienização das mãos com água e sabão ou álcool gel remove a microbiota passageira e mata esses microrganismos antes que sejam levados adiante. É a medida mais simples e barata de controle de infecção. Ex.: o aluno que lava as mãos antes de calçar as luvas e depois de tirá-las impede que bactérias de um paciente cheguem ao próximo.", fonte: ANV },
  { t: "Aderido e protegido pela matriz, só sai com escovação/fio", p: "O biofilme maduro fica preso ao dente por glucanos e coagregação, e as bactérias ficam dentro de uma matriz que segura e protege. Um bochecho apenas molha a superfície, e o antisséptico mal penetra. A cerda da escova e o fio rompem essa estrutura fisicamente e arrancam o biofilme. Ex.: na evidenciação, quem só usa enxaguante continua com as faces coradas.", fonte: MM },
  { t: "Úlcera que passa de ~15 dias precisa ser avaliada", p: "As úlceras comuns (afta, trauma, herpes) cicatrizam em 7 a 14 dias depois que a causa some. Úlcera que continua depois disso pode ser infecção crônica (tuberculose, paracoccidioidomicose) ou carcinoma espinocelular, que não cicatriza porque as células do tumor continuam crescendo. Por isso passou de cerca de 15 dias, a conduta é investigar com biópsia. Ex.: um fumante com ferida na borda da língua há 3 semanas, mesmo sem dor, precisa de biópsia.", fonte: NEV },

  /* ---------- AV 24/11 ---------- */
  { t: "destruição tecidual e tentativas de reparação podem ocorrer simultaneamente", p: "Na inflamação crônica o agressor continua presente, então as células de defesa seguem liberando enzimas e radicais que destroem tecido. Ao mesmo tempo, o corpo tenta consertar: forma novos vasos (angiogênese) e fibroblastos depositam colágeno. As duas coisas acontecem no mesmo lugar e na mesma hora. Ex.: no granuloma periapical há osso sendo reabsorvido e, ao lado, tecido fibroso novo sendo formado.", fonte: ROB },
  { t: "os plasmócitos vêm da diferenciação de linfócitos B", p: "O linfócito B ativado pelo antígeno se divide e parte das células filhas amadurece em plasmócitos, que perdem a capacidade de se dividir e passam a produzir só anticorpos. Por isso os plasmócitos aparecem nas inflamações crônicas, onde a resposta adaptativa já teve tempo de se montar. Ex.: na lâmina de uma lesão periapical crônica, os plasmócitos aparecem com o núcleo 'em roda de carroça'.", fonte: ABB },
  { t: "na tuberculose pode haver necrose caseosa central", p: "No granuloma da tuberculose, os macrófagos ativados cercam o bacilo, mas o centro fica com pouco oxigênio e cheio de restos de células e do bacilo, que tem muita gordura na parede. Essas células morrem e formam uma massa branca e esfarelada que lembra queijo (caseosa). Ex.: a biópsia de uma úlcera crônica de língua de paciente com tuberculose mostra granulomas com necrose caseosa no meio.", fonte: ROB },
  { t: "avalia proximais posteriores, cáries incipientes", p: "Na interproximal (bitewing) o feixe de raio X passa paralelo aos contatos entre os dentes posteriores, com as coroas de cima e de baixo no mesmo filme. Assim as faces proximais não ficam sobrepostas e lesões pequenas de esmalte e dentina aparecem, além da altura da crista óssea. Ex.: uma cárie entre o 36 e o 37 que não aparece no exame clínico surge como uma sombra triangular na interproximal.", fonte: WP },
  { t: "mostra áreas mais extensas que a periapical", p: "Na oclusal, o filme maior é colocado entre os dentes e o feixe vem de cima ou de baixo, mostrando todo o arco e o assoalho da boca de uma vez. A periapical mostra só 2 ou 3 dentes. Por isso a oclusal acha cálculos no ducto da submandibular, fraturas e expansões do osso. Ex.: um paciente com inchaço no assoalho faz uma oclusal inferior, que mostra o sialolito no trajeto do ducto.", fonte: WP },
  { t: "a panorâmica é 2D e não mostra a dimensão vestibulolingual", p: "A panorâmica 'achata' os maxilares curvos numa imagem plana: tudo que está à frente e atrás fica sobreposto. Ela mostra altura e largura, mas não a espessura de vestibular para lingual, nem a posição exata de uma lesão em relação ao canal mandibular. A tomografia de feixe cônico faz cortes em todas as direções e mostra em 3D. Ex.: antes de operar uma lesão grande perto do canal, o cirurgião pede tomografia para não lesar o nervo alveolar inferior.", fonte: WP },
  { t: "conforme a intensidade e a duração da agressão", p: "O mesmo agressor pode causar só adaptação ou chegar a lesão grave, dependendo de quanto age e por quanto tempo. Pouco tabaco e pouco trauma por pouco tempo dão queratose que some; muitos anos de tabaco mais trauma podem levar à displasia. Por isso não dá para prever o resultado só pela causa: é preciso biópsia e acompanhamento. Ex.: um fumante de 30 anos de cigarro com placa branca jugal vai para biópsia, mesmo sem dor.", fonte: ROB },
  { t: "linha média anterior da maxila = ducto nasopalatino", p: "O ducto nasopalatino é um canal que liga nariz e boca no embrião e fica na linha média, atrás dos incisivos centrais. Restos de epitélio desse canal podem formar cisto no adulto, e por isso o cisto aparece exatamente entre as raízes dos incisivos centrais, às vezes em forma de coração. Ex.: a radiografia oclusal superior de um adulto mostra uma imagem radiolúcida redonda bem no meio, entre os incisivos centrais, com dentes vitais.", fonte: NEV },
  { t: "crescimento agressivo = queratocisto", p: "O epitélio do queratocisto odontogênico tem células que se dividem muito mais que as de outros cistos e uma mutação (no gene PTCH) parecida com a de tumores. Ele cresce pelo osso medular, sem expandir muito a cortical, e solta 'cistos-filhos', por isso volta com frequência depois da cirurgia; o diagnóstico vem da biópsia. Ex.: uma lesão grande no ramo da mandíbula que volta 2 anos depois de removida é típica de queratocisto.", fonte: NEV },
  { t: "Antibiótico e prótese são fatores predisponentes, não diagnóstico", p: "O antibiótico mata bactérias que competiam com a Candida, e a prótese usada à noite cria um ambiente úmido e sem saliva sob ela, onde o fungo cresce. Esses fatores aumentam a chance de candidose, mas quem confirma é o exame da lesão: placa que sai na raspagem, eritema sob a prótese, às vezes citologia esfoliativa. Ex.: idosa com prótese e antibiótico recente pode ter palato vermelho por outra causa; o exame clínico decide.", fonte: NEV },
  { t: "a aparência não fecha diagnóstico", p: "O aspecto moriforme (pontinhos vermelhos na úlcera) é típico da paracoccidioidomicose, mas outras micoses profundas, a tuberculose e o carcinoma espinocelular também fazem úlceras crônicas irregulares. Só a biópsia mostra o agente (as leveduras com vários brotos) ou as células do tumor. Ex.: um trabalhador rural com úlcera moriforme na gengiva faz biópsia, que pode mostrar o fungo e, ao mesmo tempo, afastar câncer.", fonte: NEV },
  { t: "Rompeu: erosão se superficial, úlcera se profunda", p: "Vesícula e bolha têm o líquido em alturas diferentes. Se o líquido fica dentro do epitélio (como no herpes e no pênfigo), quando o teto rompe sobra parte do epitélio embaixo: é erosão. Se fica abaixo do epitélio (como no penfigóide), o rompimento expõe o conjuntivo: é úlcera. Ex.: as bolhas do pênfigo vulgar rompem e deixam erosões extensas; as do penfigóide deixam úlceras.", fonte: NEV },
  { t: "Telangiectasia = vaso DILATADO, sem extravasamento", p: "Na telangiectasia o sangue continua dentro de vasos pequenos que ficaram largos. Ao apertar com vidro (diascopia), o sangue sai do vaso e a área clareia. Na petéquia e na equimose o sangue já saiu do vaso e está no tecido, então não clareia na pressão. Ex.: pontinhos vermelhos que somem quando se aperta com um tubete são telangiectasias; os que não somem são petéquias.", fonte: NEV },
  { t: "Ausência de dor não exclui nada", p: "Lesões malignas no começo quase nunca doem, porque ainda não invadiram nervos nem ulceraram. O melanoma oral, por exemplo, não tem sintoma na grande maioria dos casos quando é descoberto. Então a falta de dor não diferencia lesão benigna de maligna; o que conta é a história (crescimento, mudança de cor, bordas irregulares) e a biópsia. Ex.: uma mancha marrom que cresceu em 3 meses no palato, sem dor, vai para biópsia.", fonte: NEV },

  /* ---------- Glossário de Interações ---------- */
  { t: "só se trata por estética", p: "A pigmentação fisiológica é só melanina a mais produzida por melanócitos normais, ligada à etnia. Ela não cresce, não vira câncer e não traz prejuízo à gengiva, então não existe motivo de saúde para tirar. Quando o paciente se incomoda com a cor no sorriso, pode-se fazer remoção cirúrgica ou com laser, só por estética. Ex.: uma paciente que acha a gengiva escura feia no sorriso largo pode optar por despigmentação, sabendo que a mancha pode voltar.", fonte: SMS },
  { t: "presentes em mais de 80% da população", p: "Durante a formação da face, glândulas sebáceas (que normalmente ficam junto dos pelos da pele) acabam ficando na mucosa da boca. Isso acontece em quase todo mundo, e elas ficam mais visíveis depois da puberdade, quando os hormônios as fazem crescer. Por ser tão comum, é considerado variação anatômica normal. Ex.: no exame clínico da turma, a maioria dos colegas adultos tem pápulas amareladas (grânulos de Fordyce) na mucosa jugal ou no lábio superior.", fonte: SMS },
  { t: "Só ocorre em áreas com dentes", p: "A linha alba é uma queratose friccional leve causada pela pressão e fricção da bochecha contra as faces dos dentes, na altura em que eles se encontram. Sem dentes, não há o que pressione a mucosa nessa linha, então ela não se forma. Ex.: um paciente desdentado total que usa prótese pode ter outras lesões, mas não tem linha alba onde não há dente.", fonte: SMS },
  { t: "somem e aparecem em outro lugar", p: "Na língua geográfica, as papilas filiformes descamam em algumas áreas, que ficam vermelhas e lisas, com borda branca de papilas se refazendo. Essas áreas cicatrizam em dias e novas áreas descamam em outro ponto, então o 'mapa' muda de lugar: por isso o nome eritema migratório. Ex.: um paciente mostra fotos da língua em dias diferentes e as manchas estão sempre em lugares diferentes.", fonte: SMS },
  { t: "Às vezes precisa ser removido para fazer prótese", p: "O tórus é osso duro coberto por mucosa fina. Uma prótese total ou parcial precisa apoiar no palato ou no rebordo lingual, e o tórus atrapalha o assentamento, cria báscula e a mucosa fina por cima machuca fácil sob a base. Nesses casos ele é removido antes da prótese. Ex.: um idoso com tórus palatino grande precisa removê-lo para usar prótese total superior estável.", fonte: SMS },
  { t: "se abre na boca na altura do segundo molar superior", p: "O ducto da parótida (Stensen), a maior glândula salivar, sai da glândula, passa sobre o masseter, atravessa o bucinador e termina na mucosa jugal numa pequena elevação, a papila parotídea, de frente para o segundo molar superior. Conhecer esse ponto evita confundir a papila com uma lesão. Ex.: um aluno que vê uma 'bolinha' na bochecha na altura do 17 está vendo a papila do ducto de Stensen.", fonte: SMS },
  { t: "comuns depois dos 60 anos", p: "Com a idade, o tecido de suporte das veias fica mais frouxo e as paredes das veias perdem elasticidade, então elas se dilatam e ficam tortuosas, igual às varizes das pernas. No ventre da língua a mucosa é fina e deixa ver esses vasos azul-violáceos. O diagnóstico é clínico e não precisam de biópsia. Ex.: no exame de um idoso de 70 anos, aparecem vários vasos arroxeados embaixo da língua (varizes linguais) que nunca deram sintoma.", fonte: SMS },
  { t: "Confirma-se quando some depois de tirar a causa", p: "A queratose friccional é uma resposta de defesa: o epitélio engrossa a camada de queratina onde algo esfrega. Se a causa (dente quebrado, grampo) é removida, o estímulo acaba e a queratina volta ao normal em algumas semanas. Uma placa que não some mesmo sem a causa não é friccional e vira suspeita de leucoplasia. Ex.: o dentista alisa um dente fraturado e, depois de 4 a 6 semanas, a placa branca da borda da língua sumiu.", fonte: SMS },
  { t: "causada principalmente pelo calor crônico do tabaco", p: "O cachimbo e o cigarro de palha produzem fumaça muito quente que bate direto no palato. O calor repetido faz o epitélio engrossar a queratina (fica branco) e inflama os ductos das glândulas salivares menores, que aparecem como pontinhos vermelhos. Por ser o calor, e não só a química, a lesão some quando a pessoa para de fumar. Ex.: um senhor que fuma cachimbo há anos tem o palato branco com pontos vermelhos.", fonte: SMS },
  { t: "tirando a prótese na hora do bochecho", p: "A Candida cresce também na resina da prótese, principalmente na base que encosta no palato. Se o bochecho com antifúngico for feito com a prótese na boca, o remédio não alcança a mucosa embaixo dela, e a prótese continua contaminada. Por isso se tira a prótese, faz o bochecho e se higieniza a prótese separadamente. Ex.: idoso com candidose sob a dentadura bochecha nistatina sem a prótese e deixa a prótese de molho na solução de limpeza.", fonte: SMS },
  { t: "Se não regredir com o tratamento, faz-se biópsia", p: "A candidose hiperplásica é branca e não sai na raspagem, como a leucoplasia, e às vezes as duas coexistem: a Candida pode infectar um epitélio que já tem displasia. Se o antifúngico resolve, era candidose; se a placa continua, é preciso biópsia para ver se há displasia epitelial. Ex.: uma placa branca na comissura que não melhora com 2 semanas de antifúngico vai para biópsia.", fonte: SMS },
  { t: "as comissuras labiais, por perda da dimensão vertical", p: "Quando o paciente perde dentes ou usa prótese gasta, a mandíbula fecha mais (perda de dimensão vertical) e os cantos da boca formam uma dobra funda. A saliva fica parada ali, a pele macera e a Candida (às vezes com estafilococo) se instala, causando fissuras e vermelhidão. Ex.: um idoso com dentadura muito gasta tem rachaduras nos dois cantos da boca que só melhoram quando a prótese é refeita.", fonte: SMS },
  { t: "quase sempre no lábio inferior", p: "O lábio inferior fica virado para a frente e para cima, e recebe o sol quase direto, enquanto o superior fica mais na sombra do nariz. A radiação UV crônica lesa o DNA das células do epitélio do vermelhão, levando à queilite actínica, que pode evoluir para carcinoma espinocelular. Ex.: um trabalhador rural de pele clara que passa o dia ao sol sem protetor labial tem o lábio inferior descamando e sem limite nítido com a pele.", fonte: SMS },
  { t: "a erosiva, se dói, trata-se com corticóide", p: "O líquen plano é causado por linfócitos T atacando as células da camada basal do epitélio. Na forma erosiva o epitélio se desfaz e expõe o conjuntivo, o que dói. O corticóide tópico diminui essa resposta imune e a inflamação, e as erosões cicatrizam. A forma reticulada (branca) não dói e só se acompanha. Ex.: uma paciente com áreas vermelhas e doloridas na bochecha por líquen plano erosivo melhora com corticóide em pomada.", fonte: SMS },
  { t: "porque indica risco de virar câncer", p: "Na displasia as células do epitélio já perderam parte da organização: núcleos grandes, divisões fora do lugar, camadas desarrumadas. São alterações que vêm antes do carcinoma espinocelular, e quanto mais intensa a displasia, maior a chance de evoluir. Por isso a biópsia de placas brancas e vermelhas procura displasia. Ex.: uma leucoplasia com displasia grave é removida e o paciente fica em acompanhamento.", fonte: SMS },
  { t: "mais na borda lateral da língua, no assoalho e no lábio inferior", p: "A borda da língua e o assoalho têm epitélio fino, não queratinizado, e ficam banhados pela saliva que acumula as substâncias do tabaco e do álcool, como numa 'poça'. O lábio inferior recebe o sol. Esses lugares levam a maior dose dos agentes cancerígenos e por isso concentram o carcinoma espinocelular. Ex.: um fumante e etilista com úlcera endurecida na borda lateral da língua precisa de biópsia urgente.", fonte: SMS },
  { t: "mancha vermelha aveludada na mucosa oral, potencialmente cancerizável", p: "A eritroplasia é vermelha porque o epitélio está fino e atrofiado, deixando ver os vasos do conjuntivo. Nas biópsias, a maioria das eritroplasias já mostra displasia grave, carcinoma in situ ou carcinoma invasivo, por isso ela tem risco de câncer maior que a leucoplasia. Ex.: uma mancha vermelha aveludada no assoalho da boca de um fumante, sem causa aparente, vai direto para biópsia.", fonte: SMS },
  { t: "pode ser preciso biópsia para descartar melanoma", p: "A tatuagem por amálgama e o melanoma podem ter a mesma cor escura. A radiografia só ajuda quando os fragmentos de metal são grandes o bastante para aparecer; se não aparecem, não dá para afirmar que é amálgama. Como errar um melanoma é grave, a mancha sem prova radiográfica vai para biópsia. Ex.: mancha negra na gengiva de paciente sem restauração metálica próxima e sem imagem na radiografia é biopsiada.", fonte: SMS },
  { t: "Como pode imitar o melanoma, recomenda-se biópsia", p: "O nevo e o melanoma inicial são feitos de melanócitos e podem parecer iguais a olho nu: mancha ou pápula marrom ou azulada. Na boca, o melanoma é mais agressivo e aparece nos mesmos lugares dos nevos (palato, gengiva). Só a biópsia mostra se as células são organizadas e benignas ou atípicas. Ex.: um nevo azul no palato é removido com biópsia excisional para ter certeza de que não é melanoma.", fonte: SMS },
  { t: "na mucosa costuma ser mais avançado e agressivo que na pele", p: "O melanoma de pele costuma ser visto cedo porque está à vista. Na boca ele fica escondido, não dói e cresce sem ser notado, além de estar numa mucosa cheia de vasos e linfáticos que facilitam a metástase. As mutações também são diferentes e respondem menos aos remédios. Ex.: a sobrevida em 5 anos do melanoma oral fica entre 15% e 35%, bem pior que a do melanoma fino de pele.", fonte: SMS },
  { t: "Trata-se removendo o tecido (com exame histopatológico) e a causa", p: "Se só a prótese for trocada, o tecido fibroso já formado geralmente não some sozinho, porque é colágeno maduro. Se só o tecido for cortado e a prótese continuar machucando, ele volta. Por isso se fazem as duas coisas. O tecido vai para exame histopatológico porque, raramente, um carcinoma pode se parecer com a hiperplasia. Ex.: um paciente tem as pregas removidas e recebe prótese nova bem adaptada.", fonte: SMS },
  { t: "vem do ligamento periodontal, só na gengiva", p: "As células gigantes dessa lesão vêm do ligamento periodontal ou do periósteo, que só existem junto dos dentes e do rebordo alveolar. Por isso ela aparece somente na gengiva ou no rebordo sem dentes, nunca na língua ou na bochecha. Ex.: um nódulo vermelho-arroxeado na gengiva entre dois pré-molares, que sangra fácil, pode ser lesão periférica de células gigantes.", fonte: SMS },
  { t: "reação exagerada a irritantes leves", p: "Irritantes pequenos e constantes, como cálculo, raiz residual ou restauração com excesso, machucam a gengiva de leve o tempo todo. O tecido responde formando tecido de granulação, mas a resposta não para e cresce demais, cheia de vasos novos. Por isso o tratamento é remover a lesão e também o irritante. Ex.: um granuloma piogênico na papila de um dente com cálculo volta se o cálculo não for raspado.", fonte: SMS },
  { t: "acredita-se que seja induzido pelo HPV", p: "O papilomavírus humano (HPV) infecta as células da camada basal do epitélio e as estimula a se multiplicar, formando projeções em forma de dedo ou couve-flor. Os tipos de HPV encontrados nos papilomas orais (6 e 11) são de baixo risco e não costumam causar câncer. Ex.: uma lesão esbranquiçada em 'couve-flor' no palato mole é removida com biópsia excisional e confirmada como papiloma.", fonte: SMS },
  { t: "raramente precisa de biópsia", p: "A úlcera traumática tem uma causa visível (dente quebrado, prótese, mordida) e cicatriza em 1 a 2 semanas depois que a causa é tirada. Se isso acontece, o próprio comportamento confirma o diagnóstico e a biópsia é desnecessária. Só se ela não cicatrizar no prazo é que se investiga. Ex.: uma úlcera na borda da língua ao lado de um dente cortante some 10 dias depois de alisar o dente.", fonte: SMS },
  { t: "curam em 7 a 10 dias", p: "A afta menor (úlcera aftosa recorrente minor) é uma úlcera rasa e pequena, causada por uma reação imune local contra o epitélio, sem infecção. Como a lesão é superficial e o organismo controla a reação em poucos dias, o epitélio se refaz rápido, sem cicatriz. Ex.: um aluno que tem afta na época de provas sabe que ela some sozinha em pouco mais de uma semana.", fonte: SMS },
  { t: "duram meses e deixam cicatriz", p: "Na afta maior a reação imune é mais intensa e destrói o epitélio e parte do conjuntivo. Uma úlcera profunda demora para se fechar e o conjuntivo perdido é substituído por fibrose, que fica como cicatriz. Ex.: um paciente com afta maior no palato mole, de 2 cm, passa semanas com dor e depois fica com uma marca.", fonte: SMS },
  { t: "por isso o diagnóstico diferencial é importante", p: "Gengiva vermelha e descamando pode vir de doenças muito diferentes: líquen plano, penfigóide ou pênfigo vulgar. O pênfigo pode matar se não for tratado e o penfigóide pode atingir os olhos, então cada uma tem tratamento e acompanhamento próprios. Só a biópsia com imunofluorescência separa uma da outra. Ex.: uma senhora com gengiva descamando é biopsiada e o resultado é penfigóide, e ela é encaminhada também ao oftalmologista.", fonte: SMS },
  { t: "úlcera crônica, endurecida e indolor", p: "Na tuberculose oral o bacilo provoca inflamação granulomatosa, com macrófagos e fibrose, e não uma inflamação aguda com muito edema. Por isso a lesão dura semanas, a base fica firme e muitas vezes dói pouco. Essa mesma descrição serve para o carcinoma espinocelular, por isso a biópsia é obrigatória. Ex.: um paciente com tuberculose pulmonar aparece com úlcera crônica no dorso da língua.", fonte: SMS },
  { t: "goma, que pode perfurar o palato", p: "Na sífilis terciária, anos depois da infecção sem tratamento, forma-se uma inflamação granulomatosa com necrose (a goma). Ela destrói o tecido em volta, e no palato pode destruir também o osso e abrir comunicação entre boca e nariz. Ex.: um paciente com sífilis nunca tratada aparece com perfuração no meio do palato duro.", fonte: SMS },
  { t: "Drenar não resolve: remove-se cirurgicamente", p: "A drenagem tira o muco, mas a glândula salivar menor continua produzindo saliva pelo ducto rompido, e a lesão volta a encher. Por isso se remove a mucocele junto com a glândula que a alimenta, e o material vai para exame histopatológico. Ex.: um paciente que teve a mucocele do lábio furada com agulha volta em uma semana com a bolinha de novo.", fonte: SMS },
  { t: "Aciclovir funciona melhor se começar cedo", p: "O aciclovir impede o vírus de copiar o DNA, mas não mata o vírus que já se multiplicou nem cura as lesões prontas. Por isso ele ajuda mais quando é usado na fase de formigamento ou nas primeiras horas, antes de o vírus se multiplicar muito. Depois de 2 a 3 dias o benefício é pequeno. Ex.: quem tem herpes labial recorrente pode passar o creme assim que sente o formigamento, antes das vesículas.", fonte: SMS },
  { t: "geralmente em crianças de 3 meses a 6 anos", p: "Até uns 3 meses o bebê ainda tem anticorpos da mãe, que recebeu pela placenta, e eles o protegem. Depois que esses anticorpos acabam, a criança fica vulnerável ao primeiro contato com o HSV-1, que acontece cedo pelos beijos e pela saliva da família. Por isso a infecção primária aparece nessa faixa. Ex.: uma criança de 2 anos com febre, gengiva muito vermelha e várias úlceras na boca, recusando comer.", fonte: SMS },
  { t: "que pode matar se não for tratada", p: "No pênfigo vulgar, anticorpos atacam as proteínas que seguram as células do epitélio umas nas outras, e o epitélio se solta em grandes áreas da pele e mucosa. Sem essa barreira, o paciente perde líquido e proteínas e fica sujeito a infecções graves, como num grande queimado. Antes do corticóide, a maioria morria. Ex.: lesões dolorosas na boca que vêm antes das bolhas na pele podem ser o primeiro sinal de pênfigo.", fonte: SMS },
  { t: "sinal de Nikolsky positivo", p: "No pênfigo as células do epitélio estão fracamente presas umas às outras por causa dos anticorpos. Uma pressão lateral firme numa área que parece normal basta para separar as camadas e formar uma bolha ou descolar o epitélio. Isso mostra que a doença está espalhada no epitélio, além das lesões visíveis. Ex.: o dentista passa o dedo firme na mucosa aparentemente sadia e ela se descola.", fonte: SMS },
  { t: "As bolhas são mais profundas e duram mais que no pênfigo", p: "No penfigóide o ataque é na ligação entre o epitélio e a membrana basal, então o epitélio inteiro se solta como um teto grosso. Esse teto aguenta mais tempo antes de romper, por isso as bolhas podem ser vistas intactas. No pênfigo vulgar a separação é dentro do epitélio, o teto é fino e rompe na hora. Ex.: no penfigóide às vezes se vê uma bolha cheia de sangue na gengiva; no pênfigo quase só se veem erosões.", fonte: SMS },
  { t: "cresce rápido e depois regride aos poucos", p: "O hemangioma infantil é um tumor benigno de células dos vasos que se multiplicam muito nos primeiros meses de vida. Depois essas células param de se dividir e começam a morrer por apoptose, e o tumor vai sendo substituído por tecido fibroso e gordura ao longo de anos. Ex.: um bebê com mancha avermelhada no lábio que cresce no primeiro ano e vai clareando até os 7 a 10 anos.", fonte: SMS },
  { t: "fica pálido na diascopia", p: "O hemangioma é feito de vasos cheios de sangue. Ao apertar com uma lâmina de vidro ou um tubete, o sangue é empurrado para fora dos vasos e a lesão perde a cor (fica pálida). Lesões com pigmento fora dos vasos, como melanina ou sangue extravasado, não clareiam. Ex.: um nódulo arroxeado no lábio que fica branco ao apertar com o tubete é lesão vascular, e não deve ser biopsiado sem planejamento.", fonte: SMS },
  { t: "sem regredir como o hemangioma", p: "A malformação vascular não é um tumor de células que se multiplicam: é um defeito de formação dos vasos, que já nascem com a estrutura errada. Como não houve proliferação, não existe a fase de involução; os vasos alterados acompanham o crescimento da pessoa e podem até aumentar com trauma ou hormônios. Ex.: uma mancha vinho no lábio de um adulto, presente desde que nasceu, é malformação e não hemangioma.", fonte: SMS },
  { t: "sem conhecer a extensão da lesão vascular causa hemorragia intensa", p: "A lesão vascular é um emaranhado de vasos cheios de sangue, às vezes com ligação com artérias. Ao cortar sem saber até onde ela vai, o sangramento pode ser difícil de controlar no consultório. Por isso primeiro se confirma pela diascopia e pela imagem e se planeja o tratamento, como a escleroterapia. Ex.: um nódulo roxo no lábio que clareia ao apertar não é biopsiado no consultório; vai para avaliação e escleroterapia.", fonte: SMS },
  { t: "o dentista deve suspeitar dela e mudar o plano de tratamento", p: "Petéquias e equimoses sem trauma mostram que o sangue não está coagulando bem ou que faltam plaquetas, o que acontece em leucemias e outras doenças do sangue. Uma extração nesse paciente pode sangrar sem parar. Por isso o dentista pede hemograma e encaminha ao médico antes de qualquer procedimento invasivo. Ex.: um jovem com pontinhos roxos no palato e gengiva sangrando sem motivo é encaminhado e recebe diagnóstico de leucemia.", fonte: SMS },
  { t: "exodontia e tratamento periodontal aumentam o risco", p: "O bisfosfonato e o denosumab diminuem a reabsorção e a renovação do osso. Depois de uma extração ou de raspagem com exposição óssea, o osso precisa se remodelar para cicatrizar; com o remédio isso fica muito lento, e o osso exposto não é coberto, necrosa e se infecta. A mandíbula, com menos circulação, é a mais afetada. Ex.: uma paciente com osteoporose em uso de bisfosfonato que extrai um molar pode ficar com osso exposto no alvéolo por meses.", fonte: SMS },
  { t: "o risco é maior quando usado na veia", p: "Pela veia o bisfosfonato chega todo ao sangue e vai em grande quantidade para o osso, e geralmente é usado em doses altas para câncer (metástase óssea, mieloma). Por via oral, só uma pequena parte é absorvida. Mais remédio no osso significa remodelação mais travada e mais chance de osteonecrose. Ex.: um paciente com metástase óssea que recebe ácido zoledrônico na veia tem risco muito maior que uma senhora que toma alendronato por boca.", fonte: SMS },
  { t: "pode ser lesão inicial da infecção pelo HIV", p: "A leucoplasia pilosa é causada pelo vírus Epstein-Barr, que quase todo mundo tem, mas que só se multiplica no epitélio da língua quando a imunidade celular cai. Por isso a lesão aparece em quem tem HIV, às vezes antes de qualquer outro sintoma, e serve de alerta. Ex.: um jovem com placas brancas verticais na borda da língua, que não saem na raspagem, deve ser orientado a fazer teste de HIV.", fonte: SMS },
  { t: "não é feita em lesão vascular", p: "Cortar uma lesão cheia de vasos sanguíneos pode causar sangramento difícil de controlar no consultório, e a biópsia nem é necessária, porque a diascopia e a imagem já mostram que é vascular. O tratamento é planejado sem corte prévio. Ex.: um hemangioma no lábio que clareia na diascopia é tratado com escleroterapia, sem biópsia.", fonte: SMS },
  { t: "Biópsia não quer dizer que é maligno", p: "A biópsia é só a forma de ver as células no microscópio. Ela é feita em muitas lesões benignas (fibroma, mucocele, nevo) e às vezes já é o próprio tratamento. Pedir biópsia significa que o dentista quer ter certeza, não que suspeita de câncer em todos os casos. Explicar isso ao paciente diminui o medo e aumenta a adesão. Ex.: o paciente com fibroma traumático na bochecha faz biópsia excisional, e o laudo confirma lesão benigna.", fonte: SMS },
  { t: "não se tira de área de necrose", p: "O tecido necrótico já está morto e desorganizado: no microscópio só se veem restos, sem as células que mostrariam a natureza da lesão. Um fragmento só de necrose pode dar laudo inconclusivo e obrigar a nova biópsia. Por isso se escolhe a borda da lesão com tecido vivo e de aspecto mais suspeito. Ex.: numa úlcera grande de língua, o fragmento é tirado da borda endurecida, e não do fundo necrótico.", fonte: SMS },
  { t: "em volume 10 a 20 vezes maior que a amostra", p: "O formol fixa o tecido entrando nele e ligando as proteínas, o que impede a decomposição. Se tiver pouco líquido, ele se gasta antes de chegar ao centro da peça, e o meio apodrece enquanto a borda fixa. Com volume bem maior que a peça, sobra formol para fixar tudo por igual. Ex.: um fragmento de biópsia de 1 cm vai para o histopatológico num frasco com pelo menos 10 a 20 mL de formol 10%.", fonte: SMS },
  { t: "mais concentrado queima o material por fora", p: "Formol muito concentrado fixa a superfície da peça rápido demais e forma uma 'casca' endurecida que impede o líquido de entrar. Assim a parte de dentro fica sem fixar e se estraga, e a de fora fica com artefatos. O formol 10% equilibra velocidade e penetração. Ex.: uma peça de biópsia colocada em formol puro chega ao laboratório dura por fora e degradada no centro, dificultando o laudo.", fonte: SMS },
  { t: "todo material removido deve ser enviado a ele", p: "Muitas lesões parecem iguais clinicamente e só o microscópio mostra o que são. Uma lesão que parece benigna e reativa pode ser carcinoma ou metástase. Se o material é jogado fora, o paciente perde a chance de diagnóstico, e o dentista fica sem prova do que tirou. Ex.: um 'granuloma piogênico' removido e enviado ao exame histopatológico revela metástase de um câncer do rim.", fonte: SMS },
  { t: "Tumor benigno mais comum das glândulas salivares", p: "O adenoma pleomórfico nasce de células dos ductos e das células mioepiteliais, que existem em grande número em todas as glândulas salivares, principalmente na parótida. Ele cresce devagar e quase não dá sintomas, então aparece muito nas séries de tumores salivares. 'Pleomórfico' vem da mistura de tecido epitelial e de aparência cartilaginosa. Ex.: um nódulo firme e indolor no palato duro, de crescimento lento, em adulto, costuma ser adenoma pleomórfico.", fonte: NEV },
  { t: "Tumor maligno mais comum das glândulas salivares", p: "O carcinoma mucoepidermoide é formado por células mucosas, epidermoides e intermediárias que vêm dos ductos, e aparece tanto nas glândulas maiores quanto nas menores, em adultos e até em crianças. Por isso é o maligno que mais aparece nas séries. Os de baixo grau crescem devagar e lembram mucocele. Ex.: um nódulo azulado no palato de adulto que parece mucocele pode ser carcinoma mucoepidermoide de baixo grau.", fonte: NEV },
  { t: "é onde mais se formam cálculos (sialolitos)", p: "A saliva da submandibular é mais grossa (mais muco), tem mais cálcio e é mais alcalina, o que favorece a precipitação de sais. Além disso, o ducto de Wharton é longo e sobe contra a gravidade até a carúncula, então a saliva fica mais tempo parada. Essas condições fazem cerca de 80% dos sialolitos aparecerem nessa glândula. Ex.: a maioria dos pacientes com 'pedra na glândula' sente o inchaço embaixo da mandíbula, e não na frente da orelha.", fonte: NEV },
  { t: "Dói e incha na hora de comer", p: "Comer e sentir o gosto da comida estimulam muito a produção de saliva. Com o ducto bloqueado pelo sialolito, essa saliva não consegue sair e fica presa dentro da glândula salivar, que incha e dói. Depois da refeição, a produção diminui e o inchaço cede. Ex.: um paciente conta que toda vez que come algo azedo a região embaixo da mandíbula incha e dói por alguns minutos.", fonte: NEV },
  { t: "benigno, mas agressivo localmente", p: "O ameloblastoma não dá metástase, por isso é benigno. Mas as células dele infiltram o osso medular além do limite que se vê na radiografia, e crescem sem parar. Se a cirurgia não tirar margem, ele volta. Por isso o tratamento costuma ser mais amplo que o de um cisto. Ex.: um ameloblastoma do corpo da mandíbula tratado só com curetagem volta anos depois.", fonte: NEV },
  { t: "Tumor odontogênico mais comum, na verdade uma malformação", p: "O odontoma tem esmalte, dentina, cemento e polpa organizados como pequenos dentes (composto) ou misturados (complexo). Ele para de crescer quando termina de se formar, igual a um dente, e não tem o crescimento autônomo de um tumor de verdade. Por isso é visto como hamartoma, uma malformação. Ex.: uma criança com um canino que não nasce tem, na radiografia, um odontoma composto com vários 'dentinhos' no caminho.", fonte: NEV },
  { t: "cresce bastante dentro do osso e volta com frequência", p: "O revestimento do queratocisto odontogênico tem células que se dividem muito, e a cápsula é fina e frágil, rasgando na cirurgia e deixando pedaços. Além disso, podem existir pequenos cistos-satélite em volta. O que fica para trás cresce de novo, por isso a recidiva é alta. Ex.: depois de remover um queratocisto da mandíbula, o paciente faz radiografias de controle por anos, procurando nova área radiolúcida.", fonte: NEV },
  { t: "Mais comum no terceiro molar inferior", p: "O cisto dentígero se forma em volta de dentes que não conseguem nascer, e o terceiro molar inferior é o dente que mais fica incluso, por falta de espaço na mandíbula. Os caninos superiores vêm em seguida. Ex.: numa panorâmica de rotina de um jovem de 20 anos, aparece uma imagem radiolúcida em volta da coroa do 38 incluso.", fonte: NEV },
  { t: "Cisto não odontogênico mais comum", p: "Na formação da face, o ducto nasopalatino liga a cavidade nasal à boca e depois se fecha, mas deixa restos de epitélio no canal incisivo de muita gente. Esses restos podem formar o cisto do ducto nasopalatino em qualquer idade, por isso é o cisto não odontogênico mais frequente. Ex.: um adulto com inchaço atrás dos incisivos centrais superiores e imagem radiolúcida na linha média, com dentes vitais.", fonte: NEV },
  { t: "mas não substitui a biópsia", p: "A citologia esfoliativa raspa só as células da superfície. Ela serve para achar Candida ou células de herpes, mas não mostra a arquitetura do tecido nem as camadas profundas, onde a displasia e o carcinoma se revelam. Um resultado 'normal' na citologia não afasta câncer. Ex.: uma placa branca suspeita com citologia negativa ainda precisa de biópsia.", fonte: NEV },
  { t: "Não somem ao apertar", p: "Na petéquia o sangue já saiu do vaso e ficou no tecido. Ao apertar com vidro (diascopia), não há vaso para esvaziar, então a cor continua. É isso que separa a petéquia de uma lesão vascular, que clareia. Ex.: pontinhos vermelhos no palato depois de sexo oral ou de tosse forte não somem ao apertar: são petéquias.", fonte: NEV },
  { t: "que somem ao apertar", p: "As telangiectasias são vasos pequenos dilatados, com sangue dentro deles. Ao apertar com vidro, o sangue é empurrado para fora do vaso e a cor some na hora; ao soltar, volta. Essa manobra (diascopia) separa lesão de vaso dilatado de sangue extravasado (petéquia). Ex.: os pontinhos vermelhos na língua e nos lábios de pacientes com telangiectasia hemorrágica hereditária clareiam ao apertar.", fonte: NEV },
  { t: "Sai com jato de água", p: "A matéria alba é um acúmulo mole de bactérias, células descamadas e restos de comida, sem a matriz organizada nem a adesão do biofilme. Como não está grudada por glucanos e coagregação, um jato de água a remove, enquanto o biofilme precisa de escova. Ex.: depois de comer, o resíduo branco perto da gengiva sai com o jato da seringa tríplice; a placa corada continua ali.", fonte: CAR },
  { t: "se desgasta logo com a mastigação", p: "A cutícula de Nasmyth é o resto do epitélio reduzido do esmalte que cobre o dente quando ele nasce. É uma camada fina e frágil, sem nenhuma renovação, que o atrito dos alimentos e da escova remove nas primeiras semanas. Ex.: um molar que acabou de nascer pode ter uma película esbranquiçada que some sozinha com a mastigação.", fonte: CAR },
  { t: "incha por acúmulo de água no citoplasma", p: "A membrana da célula tem uma bomba que gasta ATP para tirar sódio de dentro. Quando falta oxigênio ou energia, a bomba falha, o sódio se acumula dentro e puxa água junto por osmose. A célula incha e fica clara no microscópio: é a degeneração hidrópica, uma lesão reversível. Ex.: células do epitélio em volta de uma queimadura leve incham assim e voltam ao normal depois.", fonte: ROB },
  { t: "deixa a mucosa branca", p: "A queratina é uma camada grossa e seca na superfície do epitélio. Quando ela fica mais espessa, a luz não chega aos vasos vermelhos do conjuntivo e a saliva molha essa camada, que reflete a luz branca. Por isso lesões com hiperceratose, como queratose friccional e leucoplasia, aparecem brancas. Ex.: a linha alba é branca porque a mucosa ali tem mais queratina.", fonte: ROB },
  { t: "esteriliza com vapor de água sob pressão", p: "Sob pressão, a água ferve numa temperatura bem acima de 100 °C (121 a 134 °C). O vapor nessa temperatura carrega muito calor e entra em todos os cantos dos instrumentos, desnaturando as proteínas de qualquer microrganismo, inclusive esporos. Calor seco precisaria de muito mais tempo. Ex.: um pacote de instrumentos cirúrgicos sai estéril depois de um ciclo de autoclave a 134 °C.", fonte: ANV },
  { t: "Medida mais simples e importante para não passar microrganismos", p: "As mãos tocam tudo no atendimento e carregam microrganismos de um paciente para outro, para superfícies e para o próprio profissional. A higienização das mãos com água e sabão remove a sujeira e a maioria dos microrganismos passageiros, e o álcool gel os mata. Custa quase nada e reduz muito a infecção cruzada, mas não substitui a esterilização dos instrumentos. Ex.: lavar as mãos antes de calçar e depois de tirar as luvas a cada paciente.", fonte: ANV },
  { t: "Vermelho e granuloso, vira cicatriz depois", p: "O tecido de granulação é cheio de capilares novos, que dão a cor vermelha e o aspecto de pequenos grãos. Com o tempo, os fibroblastos depositam colágeno, muitos vasos regridem e o tecido fica mais pálido e firme: vira cicatriz. Ex.: o alvéolo de uma extração, depois de alguns dias, fica cheio de tecido vermelho e granuloso que depois vira osso e mucosa.", fonte: ROB },
  { t: "morto, forma o pus", p: "Os neutrófilos chegam em massa ao local da infecção, fagocitam as bactérias e liberam enzimas para destruí-las, mas morrem logo depois. O acúmulo de neutrófilos mortos, bactérias e restos de tecido liquefeito forma o líquido amarelado que chamamos de pus. Ex.: ao drenar um abscesso periapical, sai pus, que é principalmente neutrófilo morto.", fonte: ROB },
  { t: "Típica da inflamação crônica e do granuloma", p: "Os monócitos chegam ao tecido depois dos neutrófilos e viram macrófagos, que vivem semanas ou meses, fagocitam restos e produzem citocinas que mantêm a resposta. Quando o agressor é difícil de destruir, os macrófagos se ativam, se juntam e formam granulomas. Ex.: na tuberculose e na paracoccidioidomicose, os granulomas são feitos principalmente de macrófagos ativados.", fonte: ROB },
  { t: "formadas pela fusão de macrófagos", p: "Quando os macrófagos não conseguem fagocitar um agente grande ou resistente, eles se juntam e fundem as membranas, formando uma célula enorme com vários núcleos, capaz de envolver partículas maiores. Essas células gigantes aparecem nos granulomas e em reações a corpo estranho. Ex.: num granuloma da tuberculose, a lâmina mostra células gigantes com núcleos em ferradura (de Langhans).", fonte: ROB },
  { t: "uma das causas mais comuns de lesão celular", p: "Sem oxigênio, a mitocôndria não produz ATP. Sem ATP, as bombas da membrana param, a célula incha, o metabolismo vira anaeróbio e o ácido se acumula. Como quase toda célula depende de oxigênio o tempo todo, qualquer falta de circulação, anemia ou problema respiratório lesa tecidos. Ex.: no infarto, a obstrução da artéria coronária causa hipóxia e morte do músculo cardíaco.", fonte: ROB },
  { t: "Granuloma piogênico, apesar do nome, não é granuloma", p: "Granuloma, na patologia, é um agrupamento de macrófagos ativados e células gigantes. O granuloma piogênico não tem isso: é tecido de granulação cheio de vasos. E também não tem pus ('piogênico'). O nome é antigo e ficou pelo costume. Ex.: a biópsia de um granuloma piogênico da gengiva mostra muitos capilares e células inflamatórias, sem células gigantes.", fonte: ROB },
  { t: "Na saliva predomina a IgA secretora", p: "Os plasmócitos que ficam perto das glândulas salivares produzem IgA, e as células da glândula a carregam até a saliva, colocando nela um 'componente secretor' que a protege das enzimas da boca. Por isso, entre as imunoglobulinas da saliva, a IgA é a que sobra em maior quantidade e funciona na superfície das mucosas. Ex.: a IgA salivar cobre o S. mutans e dificulta sua adesão à película adquirida.", fonte: ABB },
  { t: "muitas vezes estreptococos da boca", p: "Os estreptococos do grupo viridans são os mais numerosos da boca e entram no sangue a cada escovação ou procedimento com sangramento. Eles têm proteínas que grudam bem em válvulas já alteradas e na fibrina, formando vegetações. Por isso são uma das principais causas de endocardite infecciosa. Ex.: um paciente com válvula alterada e periodontite tem uma endocardite por Streptococcus sanguis vinda da boca.", fonte: AHA },
  { t: "a altura dela mostra perda óssea periodontal", p: "Na saúde, a crista óssea fica a cerca de 1,5 a 2 mm abaixo da junção cemento-esmalte. Na periodontite a inflamação reabsorve o osso e a crista desce. A radiografia interproximal mostra essa distância sem distorção, então serve para ver e acompanhar a perda óssea. Ex.: na interproximal de um paciente com periodontite, a crista entre o 46 e o 47 está a 5 mm da junção cemento-esmalte.", fonte: WP },
  { t: "que se pega inalando o fungo no solo", p: "O Paracoccidioides vive na terra de regiões rurais e úmidas, na forma de bolor que solta esporos no ar quando o solo é mexido. A pessoa respira os esporos, que chegam ao pulmão, viram levedura e podem se espalhar para a boca. Por isso a doença aparece em lavradores e não passa de pessoa para pessoa. Ex.: um homem que trabalhou anos na roça aparece com úlcera moriforme na gengiva e lesões no pulmão.", fonte: NEV },

  /* ---------- Do glossário de Cárie que também aparece aqui ---------- */
  { t: "Só sai com remoção mecânica", p: "Depois de alguns dias, o biofilme está preso por glucanos e pela coagregação e protegido por uma matriz grossa. O bochecho apenas passa por cima, sem quebrar essa estrutura, e o antisséptico mal penetra. A escova e o fio rompem fisicamente a matriz e arrancam as bactérias da superfície. Ex.: um paciente que só usa enxaguante e não escova continua com biofilme maduro na cervical, que aparece corado na evidenciação.", fonte: "Marsh & Martin, Microbiologia Oral" },
  { t: "Dissolve quando o meio fica ácido", p: "A hidroxiapatita é um sal de cálcio e fosfato com hidroxila. O H+ do ácido se liga ao fosfato e à hidroxila, tirando esses íons do cristal. Com menos íons no meio, o cristal solta mais cálcio e fosfato para tentar equilibrar, e vai se desfazendo. Ex.: o esmalte perde mineral cada vez que o pH do biofilme cai abaixo de 5,5 depois de um doce.", fonte: "Fejerskov & Kidd, Cárie Dentária: a doença e seu tratamento clínico" },
  { t: "Não tem células, por isso não se regenera, mas pode remineralizar", p: "Os ameloblastos que formam o esmalte somem quando o dente nasce, então ninguém mais fabrica esmalte novo. O que dá para fazer é repor mineral nos cristais que perderam parte dele: cálcio e fosfato da saliva voltam aos poros quando o pH sobe, com ajuda do flúor. Um buraco (cavitação), porém, não se fecha sozinho. Ex.: uma mancha branca pode endurecer de novo; uma cavidade precisa de restauração.", fonte: "Katchburian & Arana, Histologia e Embriologia Oral" },
  { t: "Some depois que o dente erupciona", p: "O ameloblasto termina sua função quando o esmalte está completo: ele vira parte do epitélio reduzido do órgão do esmalte, que se desfaz quando o dente rompe a gengiva. Sem essas células, não existe mais produção de esmalte depois da erupção. Ex.: uma fratura de esmalte num incisivo de adulto nunca 'cresce de volta'; só pode ser restaurada.", fonte: "Katchburian & Arana, Histologia e Embriologia Oral" },
  { t: "Cada ponto a menos é 10 vezes mais ácido", p: "O pH é o logaritmo da concentração de H+ com sinal trocado: cada unidade a menos significa 10 vezes mais H+ no líquido. Por isso uma queda que parece pequena faz muita diferença para o esmalte. Ex.: um biofilme em pH 5,0 tem 100 vezes mais H+ do que em pH 7,0, o suficiente para dissolver hidroxiapatita.", fonte: "Fejerskov & Kidd, Cárie Dentária: a doença e seu tratamento clínico" },
  { t: "gruda no esmalte segundos após a limpeza", p: "As proteínas da saliva têm partes com carga que se atraem pelo cálcio e pelo fosfato do esmalte. Como a boca está sempre banhada de saliva, assim que a superfície é limpa essas proteínas já se depositam sobre ela. Por isso não existe dente 'totalmente limpo' por mais que alguns segundos. Ex.: logo depois do polimento na profilaxia, o esmalte já está coberto por uma película fina e sem bactérias.", fonte: "Marsh & Martin, Microbiologia Oral" },
  { t: "Biofilme dentro da cavidade fica protegido", p: "Quando a superfície do esmalte desaba, forma-se um buraco onde a cerda da escova não entra. O biofilme dentro dele fica parado, sem limpeza nem saliva, e mantém o pH baixo o tempo todo. Por isso a lesão cavitada costuma precisar de restauração ou de um fechamento que permita limpar. Ex.: uma cavidade oclusal pequena no 36 continua cheia de biofilme mesmo em quem escova bem.", fonte: "Fejerskov & Kidd, Cárie Dentária: a doença e seu tratamento clínico" },
  { t: "fica latente no gânglio do nervo trigêmeo", p: "Na primeira infecção, o HSV-1 entra pelas terminações nervosas da boca e sobe pelo nervo até o gânglio trigeminal, onde 'adormece' dentro do neurônio, fora do alcance dos anticorpos. Em situações de estresse, sol, febre ou baixa imunidade, ele desce pelo nervo e causa o herpes labial no mesmo lugar. Como é vírus e não bactéria, não aparece no Método de Gram e antibiótico não trata. Ex.: um aluno que sempre tem herpes labial na semana de provas está tendo reativação do vírus latente.", fonte: "Neville et al., Patologia Oral e Maxilofacial, 4ª ed." },
  { t: "Só sai com raspagem profissional", p: "O cálculo é biofilme que mineralizou com cálcio e fosfato da saliva e ficou duro como pedra, preso na superfície do dente. A escova e o fio não conseguem quebrar esse depósito, então é preciso cureta ou ultrassom no consultório. Ex.: o tártaro na lingual dos incisivos inferiores, perto da saída das glândulas, só sai com raspagem.", fonte: "Newman et al., Carranza Periodontia Clínica" },

  /* ---------- Complementos ---------- */
  { t: "A película adquirida (proteínas da saliva) se forma em minutos", p: "As proteínas da saliva têm partes com carga que se atraem pelo cálcio e pelo fosfato do esmalte, e a boca está sempre banhada de saliva. Assim, logo depois da limpeza, essas proteínas já se depositam na superfície e formam a película adquirida, ainda sem bactérias. É nela que os colonizadores iniciais vão se prender. Ex.: minutos depois do polimento na profilaxia, o esmalte já tem película, e em poucas horas os primeiros estreptococos.", fonte: MM },
  { t: "depois as bactérias pioneiras (estreptococos)", p: "Os estreptococos têm adesinas que reconhecem as proteínas da película adquirida, toleram oxigênio e estão em grande número na saliva, então são os primeiros a grudar. Ao crescer, eles consomem oxigênio e oferecem receptores para outras espécies, que chegam depois por coagregação (colonizadores tardios). Ex.: no biofilme de 4 horas quase tudo são cocos Gram-positivos em cadeia, os estreptococos.", fonte: MM },
  { t: "O corante mancha resina e aparelho", p: "O evidenciador é um corante forte, feito para tingir o biofilme. A resina composta tem pequenos poros e uma matriz orgânica que absorvem o corante, e as borrachas e o adesivo do aparelho ortodôntico também. A mancha pode não sair só com escovação. Por isso quem tem resina visível na frente ou aparelho não fez a evidenciação na aula. Ex.: um colega com bráquetes poderia ficar com as borrachinhas rosadas por dias depois da evidenciação de placa.", fonte: CAR },
  { t: "permitindo mostrar ao paciente onde a escovação está falhando", p: "O biofilme tem quase a cor do dente, então o paciente não enxerga onde está deixando placa. Corado pelo evidenciador, ele vê na hora as faces que a escova não alcança, e o dentista calcula o índice de O'Leary para comparar depois. Ver com os próprios olhos motiva mais que ouvir uma orientação genérica. Ex.: o paciente vê a faixa rosa na lingual dos molares inferiores e passa a escovar melhor ali.", fonte: CAR },
  { t: "onde é comum morder e machucar os ductos", p: "O lábio inferior fica na frente dos incisivos e é mordido com frequência, por hábito ou acidente, e tem muitas glândulas salivares menores logo abaixo da mucosa. A mordida rompe o ducto de uma delas e o muco escapa para o conjuntivo, formando a mucocele. O lábio superior é bem menos traumatizado. Ex.: uma criança que levou uma batida no lábio de baixo aparece dias depois com uma bolinha azulada e mole.", fonte: NEV },
  ]);
})();
